			assertEquals(3L, weights[0]);
			assertEquals(0, rows.read(ids, weights));
			assertTrue(rows.nextRow());
			assertEquals(2, rows.read(ids, weights));
			assertEquals(200L, ids[0]);
			assertEquals(2L, weights[0]);
			assertEquals(201L, ids[1]);
